import {openNoticeboard} from './noticeboard-tools.js';
import {openPostOffice} from './post-tools.js';
import {openPhotoTools} from './photo-tools.js';
import {FLOWER_RECIPES,gardenMessage} from '../state/garden.js';
import {SLOTS,ITEM_LABELS} from '../world/rooms.js';
const $=s=>document.querySelector(s);
export function createVillageTools({ui:baseUI,getProgress,transact,openPreparation,getView,photoStore,savePhoto,createPhotoSession}){
 let activeCleanup=null;const ui={...baseUI,workshop(title,body,mount){return baseUI.workshop(title,body,()=>{const done=mount?.();let active=true;const cleanup=()=>{if(!active)return;active=false;done?.();if(activeCleanup===cleanup)activeCleanup=null;};activeCleanup=cleanup;return cleanup;});}};
 function open(target){if(target.tool==='noticeboard')return openNoticeboard({ui});if(target.tool==='post')return openPostOffice({ui,getProgress,transact});if(target.tool==='photo'||target.tool==='photoWall')return openPhotoTools({ui,getProgress,transact,photoStore,savePhoto,createSession:createPhotoSession},{camera:target.tool==='photo'});if(target.tool==='craft')return craft();if(target.tool==='bakery')return bakery();return false;}
 function craft(){let selected='flower-vase';return ui.workshop('작은 공방 · 나의 첫 작업',`<p>꽃잎과 조개, 낙엽으로 작업대에서 작은 장식을 만들어요. 완성한 물건은 집의 선반이나 탁자에 놓을 수 있어요.</p><button id="shell-frame-prepare" class="gathered-link">조개 액자 작업대 · 조개 3개</button><button id="leaf-frame-prepare" class="gathered-link">낙엽 액자 작업대 · 낙엽 3개</button><div class="village-recipe-cards">${Object.entries(FLOWER_RECIPES).map(([id,r])=>`<button data-recipe="${id}" aria-pressed="false"><span class="recipe-model">${id==='flower-vase'?'⚘':'❀'}</span><strong>${r.label}</strong><small>꽃잎 ${r.cost}개</small></button>`).join('')}</div><p id="craft-material" class="village-note"></p><p id="village-result" role="status" aria-live="polite"></p><button id="village-craft" class="primary">작업대에서 만들기</button><section id="craft-placement"><h3>집에 놓을 자리</h3><div class="choice-row">${Object.entries(SLOTS).map(([id,s])=>`<button data-shop-slot="${id}">${s.label}</button>`).join('')}</div><p class="caption">다른 물건이 있으면 보관함으로 돌아가요. 집의 기존 가구는 그대로예요.</p></section>`,()=>{
  let alive=true;$('#leaf-frame-prepare').onclick=()=>{if(alive)baseUI.switchTo?.(()=>openPreparation?.('leaf-frame'));};$('#shell-frame-prepare').onclick=()=>baseUI.switchTo?.(()=>openPreparation?.('shell-frame'));function render(){const p=getProgress(),owned=p.ownedItemIds.includes(selected);$('#craft-material').textContent=`모은 꽃잎 ${p.garden.petals}개 · ${gardenMessage(p.garden)}`;for(const b of document.querySelectorAll('[data-recipe]'))b.setAttribute('aria-pressed',String(b.dataset.recipe===selected));$('#village-craft').disabled=owned||p.garden.petals<FLOWER_RECIPES[selected].cost;$('#village-craft').textContent=owned?'이미 만든 장식이에요':'꽃잎으로 만들기';$('#craft-placement').hidden=!owned;}
  document.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>{selected=b.dataset.recipe;$('#village-result').textContent='';render();});$('#village-craft').onclick=()=>{const result=transact({type:'CRAFT_ITEM',itemId:selected});if(!alive)return;render();$('#village-result').textContent=result?'완성했어요! 아래에서 집의 자리를 골라요':'저장하지 못해 꽃잎을 쓰지 않았어요. 저장 안내를 확인해 주세요.';};
  document.querySelectorAll('[data-shop-slot]').forEach(b=>b.onclick=()=>{const p=getProgress(),slot=b.dataset.shopSlot;if(p.placements[slot]===selected){$('#village-result').textContent='이미 이 자리에 놓여 있어요';return;}const result=transact({type:'PLACE_ITEM',slotId:slot,itemId:selected});$('#village-result').textContent=result?`${SLOTS[slot].label}에 ${ITEM_LABELS[selected]}을 놓았어요. 지도로 집에 가서 볼까요?`:'저장하지 못해 배치를 바꾸지 않았어요';});render();return()=>{alive=false;};});}
 function bakery(){return ui.workshop('밀구름 카페 · 작은 케이크',`<p>반죽 → 굽기 → 꾸미기, 세 번의 손길로 완성해요. 오븐은 바로 구워 주어요.</p><div class="bakery-steps"><button data-bake="BAKE_DOUGH"><span>1</span>반죽 빚기</button><button data-bake="BAKE_OVEN"><span>2</span>오븐에 굽기</button><div><span>3</span>마무리 장식<div class="choice-row"><button data-topping="berry">딸기 장식</button><button data-topping="star">별사탕 장식</button></div></div></div><div class="cake-preview" id="cake-preview" aria-hidden="true"></div><p id="bakery-state" role="status" aria-live="polite"></p><p id="village-result" role="status" aria-live="polite"></p><button data-bake="BAKE_NEW" class="secondary">다음 케이크 만들기</button><p class="caption">완성한 케이크와 만드는 순서는 이 브라우저에 저장돼요. 창을 닫아도 다음 단계부터 이어져요.</p>`,()=>{function render(){const b=getProgress().village.bakery;const labels={empty:'먼저 동그란 반죽을 빚어요',dough:'반죽을 빚었어요. 이제 오븐에 넣어요',baked:'노릇하게 구워졌어요. 장식을 골라요',complete:'작은 케이크 완성!'};$('#bakery-state').textContent=`${labels[b.phase]} · 완성 ${b.completed}개 / 보관 ${b.pastries}개`;$('#cake-preview').dataset.phase=b.phase;$('#cake-preview').dataset.topping=b.decoration??'';$('#cake-preview').innerHTML=b.phase==='empty'?'<span class="empty-tray">반죽을 기다리는 접시</span>':`<span class="cake-body"><i></i>${b.phase==='complete'?'<b>● ● ●</b>':''}</span>`;for(const x of document.querySelectorAll('[data-bake]'))x.disabled=b.phase!==({BAKE_DOUGH:'empty',BAKE_OVEN:'dough',BAKE_NEW:'complete'}[x.dataset.bake])||b.completed>=999;document.querySelectorAll('[data-topping]').forEach(x=>x.disabled=b.phase!=='baked');getView()?.villageView?.update(getProgress().village);}
  const act=a=>{const ok=transact(a);render();$('#village-result').textContent=ok?'':'저장하지 못해 다음 단계로 넘기지 않았어요. 저장 안내를 확인해 주세요.';};document.querySelectorAll('[data-bake]').forEach(b=>b.onclick=()=>act({type:b.dataset.bake}));document.querySelectorAll('[data-topping]').forEach(b=>b.onclick=()=>act({type:'BAKE_DECORATE',decoration:b.dataset.topping}));render();return()=>{};});}
 return {open,cancel(){activeCleanup?.();}};
}
